public int linearDp(int n, int[] arr) {
    if (n == 0) return 0;
    if (n == 1) return arr[0];
    int[] dp = new int[n];
    dp[0] = arr[0];
    dp[1] = Math.max(arr[0], arr[1]);
    for (int i = 2; i < n; i++) {
        dp[i] = Math.max(dp[i - 1], dp[i - 2] + arr[i]);
    }
    return dp[n - 1];
}

public int knapsack01(int n, int W, int[] weights, int[] values) {
    int[] dp = new int[W + 1];
    for (int i = 0; i < n; i++) {
        for (int w = W; w >= weights[i]; w--) {
            dp[w] = Math.max(dp[w], values[i] + dp[w - weights[i]]);
        }
    }
    return dp[W];
}

public int longestCommonSubsequence(String text1, String text2) {
    int m = text1.length(), n = text2.length();
    int[][] dp = new int[m + 1][n + 1];
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (text1.charAt(i - 1) == text2.charAt(j - 1)) {
                dp[i][j] = 1 + dp[i - 1][j - 1];
            } else {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    return dp[m][n];
}

public int intervalDp(int n, int[][] cost) {
    int[][] dp = new int[n][n];
    for (int length = 2; length <= n; length++) {
        for (int i = 0; i <= n - length; i++) {
            int j = i + length - 1;
            dp[i][j] = Integer.MAX_VALUE;
            for (int k = i; k < j; k++) {
                dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j] + cost[i][j]);
            }
        }
    }
    return dp[0][n - 1];
}

public int gridPaths(int m, int n, int[][] grid) {
    int[][] dp = new int[m][n];
    dp[0][0] = grid[0][0] == 0 ? 1 : 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 0) {
                if (i > 0) dp[i][j] += dp[i - 1][j];
                if (j > 0) dp[i][j] += dp[i][j - 1];
            }
        }
    }
    return dp[m - 1][n - 1];
}

public int maxProfit(int[] prices) {
    if (prices == null || prices.length == 0) return 0;
    int hold = Integer.MIN_VALUE, sold = 0, rest = 0;
    for (int p : prices) {
        int prevHold = hold, prevSold = sold, prevRest = rest;
        hold = Math.max(prevHold, prevRest - p);
        rest = Math.max(prevRest, prevSold);
        sold = prevHold + p;
    }
    return Math.max(sold, rest);
}

private int maxDiameter = 0;

public int diameterOfBinaryTree(TreeNode root) {
    dfs(root);
    return maxDiameter;
}

private int dfs(TreeNode node) {
    if (node == null) return 0;
    int left = dfs(node.left);
    int right = dfs(node.right);
    maxDiameter = Math.max(maxDiameter, left + right);
    return Math.max(left, right) + 1;
}

public int tsp(int[][] dist, int n) {
    int[][] dp = new int[1 << n][n];
    for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE / 2);
    dp[1][0] = 0;
    for (int mask = 1; mask < (1 << n); mask++) {
        for (int u = 0; u < n; u++) {
            if ((mask & (1 << u)) != 0) {
                for (int v = 0; v < n; v++) {
                    if ((mask & (1 << v)) == 0) {
                        dp[mask | (1 << v)][v] = Math.min(dp[mask | (1 << v)][v], dp[mask][u] + dist[u][v]);
                    }
                }
            }
        }
    }
    int ans = Integer.MAX_VALUE;
    for (int i = 1; i < n; i++) {
        ans = Math.min(ans, dp[(1 << n) - 1][i] + dist[i][0]);
    }
    return ans;
}

public int countNumbers(String upperBoundStr) {
    int n = upperBoundStr.length();
    Integer[][][] memo = new Integer[n][2][2];
    return digitDp(0, 1, 1, upperBoundStr, memo);
}

private int digitDp(int pos, int tight, int leadingZero, String s, Integer[][][] memo) {
    if (pos == s.length()) {
        return leadingZero == 1 ? 0 : 1;
    }
    if (memo[pos][tight][leadingZero] != null) return memo[pos][tight][leadingZero];

    int limit = tight == 1 ? s.charAt(pos) - '0' : 9;
    int ans = 0;
    for (int d = 0; d <= limit; d++) {
        int nextTight = (tight == 1 && d == limit) ? 1 : 0;
        int nextLeadingZero = (leadingZero == 1 && d == 0) ? 1 : 0;
        ans += digitDp(pos + 1, nextTight, nextLeadingZero, s, memo);
    }
    return memo[pos][tight][leadingZero] = ans;
}

public int maxSumSlidingWindow(int[] arr, int k) {
    int n = arr.length;
    int[] dp = new int[n + 1];
    Deque<Integer> dq = new ArrayDeque<>();
    dq.offer(0);
    for (int i = 1; i <= n; i++) {
        while (!dq.isEmpty() && dq.peekFirst() < i - k) dq.pollFirst();
        dp[i] = dp[dq.peekFirst()] + arr[i - 1];
        while (!dq.isEmpty() && dp[dq.peekLast()] <= dp[i]) dq.pollLast();
        dq.offerLast(i);
    }
    return dp[n];
}

public double expectedValue(double[][] probabilities, int target) {
    double[] dp = new double[target + 1];
    dp[target] = 1.0;
    for (int state = target - 1; state >= 0; state--) {
        for (double[] transition : probabilities[state]) {
            int nextState = (int) transition[0];
            double prob = transition[1];
            dp[state] += prob * dp[nextState];
        }
    }
    return dp[0];
}

public int partitionArray(int[] arr, int K) {
    int n = arr.length;
    int[][] dp = new int[n + 1][K + 1];
    for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE / 2);
    dp[0][0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int k = 1; k <= K; k++) {
            for (int j = 0; j < i; j++) {
                dp[i][k] = Math.min(dp[i][k], dp[j][k - 1] + computeCost(j, i - 1));
            }
        }
    }
    return dp[n][K];
}

public int[] sosDp(int[] arr, int n) {
    int[] dp = new int[1 << n];
    for (int i = 0; i < (1 << n); i++) dp[i] = arr[i];
    for (int i = 0; i < n; i++) {
        for (int mask = 0; mask < (1 << n); mask++) {
            if ((mask & (1 << i)) != 0) {
                dp[mask] += dp[mask ^ (1 << i)];
            }
        }
    }
    return dp;
}

public int threeDimensionalDp(String A, String B, String C) {
    int l = A.length(), m = B.length(), n = C.length();
    int[][][] dp = new int[l + 1][m + 1][n + 1];
    for (int i = 1; i <= l; i++) {
        for (int j = 1; j <= m; j++) {
            for (int k = 1; k <= n; k++) {
                if (A.charAt(i - 1) == B.charAt(j - 1) && B.charAt(j - 1) == C.charAt(k - 1)) {
                    dp[i][j][k] = 1 + dp[i - 1][j - 1][k - 1];
                } else {
                    dp[i][j][k] = Math.max(dp[i - 1][j][k], Math.max(dp[i][j - 1][k], dp[i][j][k - 1]));
                }
            }
        }
    }
    return dp[l][m][n];
}
